window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-7501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βῆσσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra β · nº geral 7501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cavidade; profundeza 2 vale 3 taça.</p></section></article>\n<article id=\"entry-dgp-7502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βήσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra β · nº geral 7502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. βήττω (fut. βήξω, aor. ἔβηξα, perf. desus.) 1 tos­sir 2 Medic. expectorar ♦ méd. 3 tossir. 〈βήξ〉</p></section></article>\n<article id=\"entry-dgp-7503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βητάρμων, ονος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra β · nº geral 7503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dançarino ♦ adj. 2 tard. que dança. 〈βαίνω, ἀραρίσκω〉</p></section></article>\n<article id=\"entry-dgp-7504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βήτην</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra β · nº geral 7504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a dual aor.2 poét. de βαίνω.</p></section></article>\n<article id=\"entry-dgp-7505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βία, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra β · nº geral 7505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. βίη, ης (ἡ) 1 força; grande força; potência 2 força vital; vida 3 uso da força ou abuso da força; violência; forçamento; βίᾳ, βίῃ, βίηφι ou ἀπό, διά, ἐκ, ὑπὸ βίας ou πρὸς βίαν pela força; à força; por violência; βίᾳ τινός contra a vontade de alguém; a despeito de alguém 4 pl. atos de violência; brutalidades 5 Βίη person. a Força ou a Violência.</p></section></article>\n<article id=\"entry-dgp-7506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra β · nº geral 7506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐβίαζον, aor. ἐβίασα) 1 empregar a força: εἰ πάνυ ἐβίαζον hipócr. se empregassem plenamente a força 2 empregar a força contra; constranger alguém, ac.: ἦ μάλα δή με βιάζετε μοῦνον ἐόντα hom. como sou um só; vós me coagis ♦ méd. 3 usar a força; agir com violência: ὡς νεοζυγὴς πῶλος βιάζῃ ésql. como um potro recém-domado reage com violência, μὴ τοίνυν ἐᾶτε ταῦτ’ αὐτὸν λέγειν, μηδ’, ἂν βιάζηται, πείθεσθε dem. não permitais que ele fale disso, e se ele forçar, não escuteis 4 tratar com violência; dominar pela força alguém, ac.: βιάζεσται ἀνθρώπους xen. maltratar os homens 5 coagir alguém, ac., a, inf.: βιάζεσθαι μὴ βουλομένους ἀκούειν dem. forçá-los, mesmo que não queiram, a escutar 6 impor pela força; tomar pela força: ἀπόβασιν, ἐκπλοῦν β. tuc. forçar um desembarque; forçar a saída de um porto 7 sustentar veementemente; defender obstinadamente: ἔχθραν ἣν οὗτος αὑτῷ πρὸς ἐμέ... φησὶν εἷναι καὶ βιάζεται dem. a inimizade que ele afirma e sustenta com obstinação. 〈βία〉</p></section></article>\n<article id=\"entry-dgp-7507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιαιοθανατέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra β · nº geral 7507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βιαιοθανατήσω) morrer de morte violenta. 〈βίαιος, θάνατος〉</p></section></article>\n<article id=\"entry-dgp-7508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βίαιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra β · nº geral 7508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 que age com violência; violento impetuoso 2 levado pela violência; forçado; constrangido. 〈βία〉</p></section></article>\n<article id=\"entry-dgp-7509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιαίως</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra β · nº geral 7509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com violência; violentamente 2 com força; fortemente 3 de modo forçado; contrariamente à natureza.</p></section></article>\n<article id=\"entry-dgp-7510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra β · nº geral 7510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 violência; violação 2 pl. acessos violentos (de um mal). 〈βιάζω〉</p></section></article>\n<article id=\"entry-dgp-7511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιαστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra β · nº geral 7511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. pessoa que usa de violência. 〈βιάζω〉</p></section></article>\n<article id=\"entry-dgp-7512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra β · nº geral 7512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(at. só 3ª sing. perf. βεβίηκε; pas. pres., fut. desus., aor. ἐβιήθην, perf. βεβίημαι) 1 at. e méd. forçar; constranger; oprimir ♦ méd. 2 abusar; usurpar; roubar 3 vio­lentar; violar. 〈βία〉</p></section></article>\n<article id=\"entry-dgp-7513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra β · nº geral 7513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., part. fut. βιβῶν, aor. ἐβίβασα; pas. só part. aor. βιβασθείς) 1 fazer ir; fazer subir 2 fazer cobrir (o macho à fêmea). 〈βαίνω〉</p></section></article>\n<article id=\"entry-dgp-7514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβάσθων</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra β · nº geral 7514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. masc. em μακρὰ βιβάσθων hom. que dá grandes passadas.</p></section></article>\n<article id=\"entry-dgp-7515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βίβημι</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra β · nº geral 7515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres. masc. βιβάς, ac. masc. βιβάντα, fem. βιβᾶσα) dar grandes passos.</p></section></article>\n<article id=\"entry-dgp-7516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβλαρίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra β · nº geral 7516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = βιβλάριον.</p></section></article>\n<article id=\"entry-dgp-7517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβλάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra β · nº geral 7517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. livrinho.</p></section></article>\n<article id=\"entry-dgp-7518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβλιακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra β · nº geral 7518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conhecedor de livros; leitor de livros; douto 2 pedante 3 referente a livro. 〈βιβλίον〉</p></section></article>\n<article id=\"entry-dgp-7519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβλιδάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra β · nº geral 7519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βιβλίδιον.</p></section></article>\n<article id=\"entry-dgp-7520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβλίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra β · nº geral 7520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">livrinho.</p></section></article>\n<article id=\"entry-dgp-7521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβλίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra β · nº geral 7521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 folha de papiro; folha de papel 2 folha escrita; carta; libelo; documento; petição 3 tabuinha para escrever 4 livro ♦ τὰ βιβλία 5 coleção de livros, partic. a Bíblia. 〈βίβλος〉</p></section></article>\n<article id=\"entry-dgp-7522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βίβλος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra β · nº geral 7522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βύβλος.</p></section></article>\n<article id=\"entry-dgp-7523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβρώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 319 na letra β · nº geral 7523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βρώσομαι, aor.2 ἔβρων, perf. βέβρωκα; pas. fut. βρωθήσομαι, aor. ἐβρώθην, perf. βέβρωμαι, fut. ant. βεβρώσομαι) comer avidamente; devorar.</p></section></article>\n<article id=\"entry-dgp-7524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιβῶν</h1><div class=\"entry-meta\"><span>DGP · ordem 320 na letra β · nº geral 7524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. fut. de βιβάζω.</p></section></article>\n<article id=\"entry-dgp-7525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βίη</h1><div class=\"entry-meta\"><span>DGP · ordem 321 na letra β · nº geral 7525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = βία.</p></section></article>\n<article id=\"entry-dgp-7526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιήσατο</h1><div class=\"entry-meta\"><span>DGP · ordem 322 na letra β · nº geral 7526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. ép. de βιάω.</p></section></article>\n<article id=\"entry-dgp-7527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βίηφι</h1><div class=\"entry-meta\"><span>DGP · ordem 323 na letra β · nº geral 7527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. ép. de βία.</p></section></article>\n<article id=\"entry-dgp-7528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βῖκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 324 na letra β · nº geral 7528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ânfora ou jarro 2 vasilha para beber. [semít.]</p></section></article>\n<article id=\"entry-dgp-7529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιόδωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 325 na letra β · nº geral 7529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que dá a vida. 〈βίος, δίδωμι〉</p></section></article>\n<article id=\"entry-dgp-7530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βίος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 326 na letra β · nº geral 7530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gênero de vida; vida; existência: ἀκίνδυνον βίον ζῶμεν eur. vivemos uma vida sem perigos 2 duração da vida; tempo de vida; vida: τὸν λοιπὸν βίον xen. pelo resto da vida, πέρας μὲν γὰρ ἅπασιν ἀνθρώποις ἐστὶ τοῦ βίον θάνατος dem. para todos os homens há um termo de vida, a morte 3 poét. e rar. vida; princípio vital: ἐξέπνευσεν βίον eur. deu o último suspiro 4 recursos para viver; meios de subsistência; sustento: βίον ποιεῖσθαι xen. providenciar recursos, οἱ λοιποὶ βίοι pol. os outros meios de vida 5 vida; vida do mundo; mundo 6 humanidade: οἱ ἀπὸ τοῦ βίου s.e. as pessoas do mundo 7 lugar onde se vive; residência: βίους ἱδρύσαντο d.h. construíram habitações.</p></section></article>\n<article id=\"entry-dgp-7531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 327 na letra β · nº geral 7531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arco.</p></section></article>\n<article id=\"entry-dgp-7532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιοστερής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 328 na letra β · nº geral 7532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sem recursos. 〈βίος, στερέω〉</p></section></article>\n<article id=\"entry-dgp-7533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιοτεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 329 na letra β · nº geral 7533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">modo de vida. 〈βιοτεύω〉</p></section></article>\n<article id=\"entry-dgp-7534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιοτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 330 na letra β · nº geral 7534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βιοτεύσω) 1 viver 2 abastecer-se de recursos para viver 3 residir; habitar.</p></section></article>\n<article id=\"entry-dgp-7535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιοτή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 331 na letra β · nº geral 7535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vida; gênero de vida 2 meios de subsistência.</p></section></article>\n<article id=\"entry-dgp-7536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιότιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 332 na letra β · nº geral 7536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vida insignificante. 〈βίοτος〉</p></section></article>\n<article id=\"entry-dgp-7537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βίοτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 333 na letra β · nº geral 7537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vida 2 meios de subsistência; recursos; bens 3 a vida; os homens; o mundo. 〈βίος〉</p></section></article>\n<article id=\"entry-dgp-7538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιούς</h1><div class=\"entry-meta\"><span>DGP · ordem 334 na letra β · nº geral 7538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part aor.2 de βιόω.</p></section></article>\n<article id=\"entry-dgp-7539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 335 na letra β · nº geral 7539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐβίουν, fut. βιώσομαι, aor. ἐβίωσα, aor.2 ἐβίων, perf βεβίωκα) 1 viver: β. μέχρι γήρως viver até a velhice, β. μετρίως viver com moderação; perf. pas. βεβίωταί μοι dem. para mim, a vida já passou, τὰ σοὶ κἀμοὶ βεβιωμένα dem. a vida vivida por mim e por ti ♦ at. e méd. 2 sobreviver: ἀπολέσθαι ἠὲ βιῶναι hom. morrer ou viver 3 aor. méd. dar a vida a; salvar: σὺ γὰρ μ’ ἐβιώσαο, κούρη hom. tu me deste a vida, menina. 〈βίος〉</p></section></article>\n<article id=\"entry-dgp-7540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιόωνται, βιόωντο</h1><div class=\"entry-meta\"><span>DGP · ordem 336 na letra β · nº geral 7540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. pres. e impf. méd. ép. de βιάω.</p></section></article>\n<article id=\"entry-dgp-7541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιῴατο</h1><div class=\"entry-meta\"><span>DGP · ordem 337 na letra β · nº geral 7541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. pres. opt. méd. de βιάομαι.</p></section></article>\n<article id=\"entry-dgp-7542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιῶναι</h1><div class=\"entry-meta\"><span>DGP · ordem 338 na letra β · nº geral 7542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. de βιόω, em hom. com sent. de pres.</p></section></article>\n<article id=\"entry-dgp-7543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιώσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 339 na letra β · nº geral 7543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se pode viver: β. χρόνος eur. tempo que temos para viver 2 que torna a vida suportável: οὐ βιώσιμόν ou βιώσιμά ἐστι μοι her. não me é possível viver. 〈βιόω〉</p></section></article>\n<article id=\"entry-dgp-7544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βίωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 340 na letra β · nº geral 7544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. meios de vida; recursos de subsistência. 〈βιόω〉</p></section></article>\n<article id=\"entry-dgp-7545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιωτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 341 na letra β · nº geral 7545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que diz respeito à vida; da vida 2 que provê para si os meios de vida 3 crist. relativo à vida terrena ou cotidiana ♦ ἡ βιωτική 4 a arte da vida; a moral prática ♦ τὰ βιωτικά 5 coisas da vida. 〈βιόω〉</p></section></article>\n<article id=\"entry-dgp-7546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 342 na letra β · nº geral 7546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se deve ou que se pode viver: βίος οὐ βιωτός sóf. vida que não se pode viver; vida intolerável, οὐ βιωτόν [ἐστι] dem. não é uma vida tolerável, ἀρ’ οὖν βιωτὸν ἡμῖν ἐστιν μετὰ μοχθηροῦ σώματος; plat. para nós, então, será possível viver com um corpo malsão? 〈βιόω〉</p></section></article>\n<article id=\"entry-dgp-7547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βιώτω</h1><div class=\"entry-meta\"><span>DGP · ordem 343 na letra β · nº geral 7547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. imper. aor.2 de βιόω.</p></section></article>\n<article id=\"entry-dgp-7548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλάβεν</h1><div class=\"entry-meta\"><span>DGP · ordem 344 na letra β · nº geral 7548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. ind. aor.2 ép. de βλάπτω.</p></section></article>\n<article id=\"entry-dgp-7549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαβερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 345 na letra β · nº geral 7549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nocivo; funesto; pernicioso. 〈βλάπτω〉</p></section></article>\n<article id=\"entry-dgp-7550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαβερῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 346 na letra β · nº geral 7550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo funesto.</p></section></article>\n<article id=\"entry-dgp-7551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλάβη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 347 na letra β · nº geral 7551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estrago; dano; prejuízo: βλάβης δίκη dem. ação judiciária por dano 2 flagelo (pessoa): βλάβη θεοῦ eur. flagelo enviado por um deus.</p></section></article>\n<article id=\"entry-dgp-7552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαβήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 348 na letra β · nº geral 7552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. βλάπτω.</p></section></article>\n<article id=\"entry-dgp-7553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλάβος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 349 na letra β · nº geral 7553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βλάβη.</p></section></article>\n<article id=\"entry-dgp-7554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαισός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 350 na letra β · nº geral 7554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem as patas ou os pés recurvados ou torcidos 2 retorcido; torcido; disforme.</p></section></article>\n<article id=\"entry-dgp-7555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαίσωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 351 na letra β · nº geral 7555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de retorquir os termos de um dilema com termos contrários 2 curvatura; deformação. 〈βλαισός〉</p></section></article>\n<article id=\"entry-dgp-7556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλακεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 352 na letra β · nº geral 7556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">falta de ardor ou energia; moleza; inércia. 〈βλακεύω〉</p></section></article>\n<article id=\"entry-dgp-7557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλακεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 353 na letra β · nº geral 7557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βλακεύσω) 1 ter falta de ardor; agir frouxamente; ser indolente 2 perder por preguiça, ac. ♦ méd. 3 viver na indolência. 〈βλάξ〉</p></section></article>\n<article id=\"entry-dgp-7558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλακικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 354 na letra β · nº geral 7558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sem atividade; indolente; preguiçoso. 〈βλάξ〉</p></section></article>\n<article id=\"entry-dgp-7559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλακίστατος</h1><div class=\"entry-meta\"><span>DGP · ordem 355 na letra β · nº geral 7559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. de βλάξ.</p></section></article>\n<article id=\"entry-dgp-7560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλακώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 356 na letra β · nº geral 7560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">frouxo; indolente. 〈βλάξ〉</p></section></article>\n<article id=\"entry-dgp-7561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλάξ</h1><div class=\"entry-meta\"><span>DGP · ordem 357 na letra β · nº geral 7561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. βλακός (masc., fem.) (superl. βλακίστατος) 1 sem ânimo; incapaz de agir; preguiçoso 2 incapaz de decidir; de espírito preguiçoso; tardo de inteligência 3 desdenhoso.</p></section></article>\n<article id=\"entry-dgp-7562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 358 na letra β · nº geral 7562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔβλαπτον, fut. βλάψω, aor. ἔβλαψα, perf. βέβλαφα; pas. fut βλαβήσομαι, aor. ἐβλάφθην, aor.2 ἐβλάβην, perf. βέβλαμμαι) 1 entravar; embaraçar; deter: τόν γε θεοὶ βλάπτουσι κελεύθου hom. os deuses embaraçam-lhe o caminho, ἔνθ’ Αἴας μὲν ὄλισθε θέων, βλάψεν γὰρ Ἀθήνη hom. então Ajax correndo escorregou, pois Atena o barrou 2 perturbar: βλ. φρένας, τινὰ βλ. φρένας, βλ. τινά hom. perturbar a razão de alguém, βλ. νόοιο teóg. perturbar o espírito, νόου βεβλαμμένος teóg. de espírito perturbado 3 prejudicar; causar dano a; fazer mal a, ac.: ἵνα μηδ’ ἐν τούτοις τοὺς φίλους βλάπτοιτε xen. a fim de que com isso não causásseis dano aos amigos 4 violar: β. τοὺς ὄρκους artt. violar os juramentos.</p></section></article>\n<article id=\"entry-dgp-7563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαστάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 359 na letra β · nº geral 7563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐβλάστανον, fut. βλαστήσω, aor.1 ἐβλάστησα, aor.2 ἔβλαστον, perf. βεβλάστηκα e ἐβλάστηκα) 1 (plantas) brotar; crescer 2 (pessoa) nas­cer; descender de, ἐκ, ἀπό e gen. 3 brotar; surgir; germinar de, ἐκ, ἀπό e gen. 4 causat. fazer germinar. 〈βλάστη〉</p></section></article>\n<article id=\"entry-dgp-7564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαστάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 360 na letra β · nº geral 7564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = βλαστάνω.</p></section></article>\n<article id=\"entry-dgp-7565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαστέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 361 na letra β · nº geral 7565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) at. e méd. germinar; brotar; crescer. 〈βλαστός〉</p></section></article>\n<article id=\"entry-dgp-7566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλάστη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 362 na letra β · nº geral 7566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 germe; rebento 2 produção; crescimento; nascimento 3 poét. origem; filiação.</p></section></article>\n<article id=\"entry-dgp-7567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλάστημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 363 na letra β · nº geral 7567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 germe; rebento 2 poét. produção; parto 3 Medic. excrescência; erupção; blastema. 〈βλαστάνω〉</p></section></article>\n<article id=\"entry-dgp-7568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαστημός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 364 na letra β · nº geral 7568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 broto 2 floração. 〈βλαστάνω〉</p></section></article>\n<article id=\"entry-dgp-7569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαστήσω</h1><div class=\"entry-meta\"><span>DGP · ordem 365 na letra β · nº geral 7569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. βλαστάνω.</p></section></article>\n<article id=\"entry-dgp-7570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαστός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 366 na letra β · nº geral 7570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 renovo; broto 2 flor 3 embrião; filho; filhote 4 germinação. 〈βλαστάνω〉</p></section></article>\n<article id=\"entry-dgp-7571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλασφημέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 367 na letra β · nº geral 7571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βλασφημήσω, aor. ἐβλασφήμησα, perf. βεβλασφήμηκα) 1 dirigir palavras profanas ou ímpias a alguém, εἰς e ac. 2 dizer injúrias; maldizer; levantar calúnias sobre alguém, περί e gen. ou εἰς e ac., contra alguém, κατά e gen. 3 tard. difamar 4 bíbl. blasfemar. 〈βλάσφημος〉</p></section></article>\n<article id=\"entry-dgp-7572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλασφημία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 368 na letra β · nº geral 7572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 palavra de mau agouro; palavra profana ou ímpia; blasfêmia 2 injúria; maledicência; calúnia. 〈βλάσφημος〉</p></section></article>\n<article id=\"entry-dgp-7573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλάσφημος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 369 na letra β · nº geral 7573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que pronuncia palavras profanas ou de mau agouro; que blasfema 2 maldizente; difamador. 〈βλάπτω, φήμη〉</p></section></article>\n<article id=\"entry-dgp-7574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαχά</h1><div class=\"entry-meta\"><span>DGP · ordem 370 na letra β · nº geral 7574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = βληχή.</p></section></article>\n<article id=\"entry-dgp-7575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλαψίφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 371 na letra β · nº geral 7575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 cuja razão sofreu dano; demente 2 tard. que faz mal à alma; que faz perder o senso. 〈βλάπτω, φρήν〉</p></section></article>\n<article id=\"entry-dgp-7576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλεῖο</h1><div class=\"entry-meta\"><span>DGP · ordem 372 na letra β · nº geral 7576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">var. de βλῆο.</p></section></article>\n<article id=\"entry-dgp-7577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλεμεαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 373 na letra β · nº geral 7577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 estar no esplendor de; orgulhar-se de, dat. ou περί e dat. 2 comprometer-se a; empenhar-se em, inf.</p></section></article>\n<article id=\"entry-dgp-7578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλέμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 374 na letra β · nº geral 7578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">olhar; golpe de vista; vista. 〈βλέπω〉</p></section></article>\n<article id=\"entry-dgp-7579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλέπος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 375 na letra β · nº geral 7579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">olhar. 〈βλέπω〉</p></section></article>\n<article id=\"entry-dgp-7580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλεπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 376 na letra β · nº geral 7580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">digno de ser visto. 〈βλέπω〉</p></section></article>\n<article id=\"entry-dgp-7581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλέπω</h1><div class=\"entry-meta\"><span>DGP · ordem 377 na letra β · nº geral 7581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔβλεπον, fut. βλέψομαι, post. βλέψω, aor. ἔβλεψα, perf. desus; pas. perf. βέβλεμμαι) 1 ter o sentido da visão; ter possibilidade de ver; ver: δεινῶς ἀθυμῶ μὴ βλέπων ὁ μάντις ἦ sóf. tenho um medo terrível de que o adivinho esteja vendo 2 olhar; olhar de um certo modo, com adv. ou part.: βλ. σεμνὸν καὶ πεφροντικός eur. olhar com ar grave e preocupado 3 lançar olhares; olhar para ver, εἰς e ac.: βλ. εἰς τὸν ἀεὶ θορυβοῦντα τόπον τῆς ἐκκλησίας dem. olhar para o lado da assembléia em constante tumulto 4 olhar; observar; notar: τὰ βλεπόμενα sóf. o universo visível, οὐ δεῖ εἰς τὴν εὐήθειαν τῆς τοῦ τότε πόλεμου βλέποντας ἐκτραχηλισθῆναι dem. é preciso que; ao verificar o caráter benigno da guerra de então; não se deixem desconcertar 5 ter em vista; aspirar a, πρός e ac.: πρὸς τὸ διαπράξασται μόνον βλέποντες plat. tendo em vista somente a realização 6 bíbl. olhar para vigiar; tomar cuidado com; desconfiar de, ac. ou ἀπό e gen.: βλέπετε τί ἀκούετε n.t. prestai atenção ao que ouvis 7 dar vista para; ficar de frente para, πρός e ac.: αἱ πρὸς μεσημβρίαν βλέπουσαι οἰκίαι xen. as casas voltadas para o sul, πρὸς ἕω βλέπουσαν ἵστασθαι τὴν σκηνήν xen. armar a tenda com a entrada voltada para o leste.</p></section></article>\n<article id=\"entry-dgp-7582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλεφαρίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 378 na letra β · nº geral 7582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cílio 2 pálpebra. 〈βλέφαρον〉</p></section></article>\n<article id=\"entry-dgp-7583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλέφαρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 379 na letra β · nº geral 7583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pálpebra 2 olho. 〈βλέπω〉</p></section></article>\n<article id=\"entry-dgp-7584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλήεται</h1><div class=\"entry-meta\"><span>DGP · ordem 380 na letra β · nº geral 7584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 pas. ép. de βάλλω.</p></section></article>\n<article id=\"entry-dgp-7585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βληθήσομαι, βληθῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 381 na letra β · nº geral 7585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. pas. e inf. aor. pas. de βάλλω.</p></section></article>\n<article id=\"entry-dgp-7586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλῆμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 382 na letra β · nº geral 7586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 golpe desferido; pancada; ferida 2 lan­çamento; arremesso 3 poét. aquilo que se lança; dardo 4 aquilo que se estende; coberta. 〈βάλλω〉</p></section></article>\n<article id=\"entry-dgp-7587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλέμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 383 na letra β · nº geral 7587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. ép. de βάλλω.</p></section></article>\n<article id=\"entry-dgp-7588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλῆο</h1><div class=\"entry-meta\"><span>DGP · ordem 384 na letra β · nº geral 7588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e βλῇο 2ª sing. opt. aor.2 pas. ép. de βάλλω.</p></section></article>\n<article id=\"entry-dgp-7589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλῆσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 385 na letra β · nº geral 7589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 pas. ép. de βάλλω.</p></section></article>\n<article id=\"entry-dgp-7590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλητέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 386 na letra β · nº geral 7590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de βάλλω.</p></section></article>\n<article id=\"entry-dgp-7591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλῆτο</h1><div class=\"entry-meta\"><span>DGP · ordem 387 na letra β · nº geral 7591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 pas. pas. de βάλλω.</p></section></article>\n<article id=\"entry-dgp-7592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 388 na letra β · nº geral 7592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atingido por apoplexia ♦ τὸ βλητόν [ζῶον] 2 animal que ataca (por op. a δακετὸν ζῷον animal que morde). 〈βάλλω〉</p></section></article>\n<article id=\"entry-dgp-7593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλῆτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 389 na letra β · nº geral 7593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prego; cavilha. 〈βάλλω〉</p></section></article>\n<article id=\"entry-dgp-7594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βληχάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 390 na letra β · nº geral 7594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐβλεχησάμην) balir; vagir. 〈βληχή〉</p></section></article>\n<article id=\"entry-dgp-7595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βληχή, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 391 na letra β · nº geral 7595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">balido; vagido.</p></section></article>\n<article id=\"entry-dgp-7596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βληχηθμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 392 na letra β · nº geral 7596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = βληχή.</p></section></article>\n<article id=\"entry-dgp-7597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βληχητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 393 na letra β · nº geral 7597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que bale ♦ τὰ βληχητά 2 animais que emitem balidos. 〈βληχάομαι〉</p></section></article>\n<article id=\"entry-dgp-7598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βληχώ, οῦς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 394 na letra β · nº geral 7598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poejo; menta selvagem.</p></section></article>\n<article id=\"entry-dgp-7599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βληχώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 395 na letra β · nº geral 7599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que bale 2 semelhante a um carneiro; tolo. 〈βληχάομαι〉</p></section></article>\n<article id=\"entry-dgp-7600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βλιμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 396 na letra β · nº geral 7600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., impf. ἐβλιμάζου e aor. pas.) 1 tatear; apalpar 2 manejar; manusear 3 Medic. massagear.</p></section></article>\n";
